typedef RGFW_ENUM(u8, RGFW_format) {
	RGFW_formatRGB8 = 0,
	RGFW_formatBGR8,
	RGFW_formatRGBA8,
	RGFW_formatARGB8,
	RGFW_formatBGRA8,
	RGFW_formatABGR8,
	RGFW_formatCount
};

typedef RGFW_ENUM(u8, RGFW_mouseButton) {
	RGFW_mouseLeft = 0,
	RGFW_mouseMiddle,
	RGFW_mouseRight,
	RGFW_mouseMisc1, RGFW_mouseMisc2, RGFW_mouseMisc3, RGFW_mouseMisc4, RGFW_mouseMisc5,
	RGFW_mouseFinal
};

typedef RGFW_ENUM(u8, RGFW_keymod) {
	RGFW_modCapsLock = RGFW_BIT(0),
	RGFW_modNumLock  = RGFW_BIT(1),
	RGFW_modControl  = RGFW_BIT(2),
	RGFW_modAlt = RGFW_BIT(3),
	RGFW_modShift  = RGFW_BIT(4),
	RGFW_modSuper = RGFW_BIT(5),
	RGFW_modScrollLock = RGFW_BIT(6)
};

typedef struct RGFW_commonEvent {
	RGFW_eventType type;
	RGFW_window* win;
} RGFW_commonEvent;

typedef struct RGFW_mouseButtonEvent {
	RGFW_eventType type;
	RGFW_window* win;
	RGFW_mouseButton value;
} RGFW_mouseButtonEvent;

typedef struct RGFW_mouseScrollEvent {
	RGFW_eventType type;
	RGFW_window* win;
	float x, y;
} RGFW_mouseScrollEvent;

typedef struct RGFW_mousePosEvent {
	RGFW_eventType type;
	RGFW_window* win;
	i32 x, y;
	float vecX, vecY;
} RGFW_mousePosEvent;

typedef struct RGFW_keyEvent {
	RGFW_eventType type;
	RGFW_window* win;
	RGFW_key value;
	u8 sym;
	RGFW_bool repeat;
	RGFW_keymod mod;
} RGFW_keyEvent;

typedef struct RGFW_dataDropEvent {
	RGFW_eventType type;
	RGFW_window* win;
	char** files;
	size_t count;
} RGFW_dataDropEvent;

typedef struct RGFW_dataDragEvent {
	RGFW_eventType type;
	RGFW_window* win;
	i32 x, y;
} RGFW_dataDragEvent;

typedef struct RGFW_scaleUpdatedEvent {
	RGFW_eventType type;
	RGFW_window* win;
	float x, y;
} RGFW_scaleUpdatedEvent;

typedef union RGFW_event {
	RGFW_eventType type;
	RGFW_commonEvent common;
	RGFW_mouseButtonEvent button;
	RGFW_mouseScrollEvent scroll;
	RGFW_mousePosEvent mouse;
	RGFW_keyEvent key;
	RGFW_dataDropEvent drop;
	RGFW_dataDragEvent drag;
	RGFW_scaleUpdatedEvent scale;
} RGFW_event;

typedef RGFW_ENUM(i32, RGFW_eventWait) {
	RGFW_eventNoWait = 0,
	RGFW_eventWaitNext = -1
};

typedef RGFW_ENUM(u8, RGFW_icon) {
	RGFW_iconTaskbar = RGFW_BIT(0),
	RGFW_iconWindow = RGFW_BIT(1),
	RGFW_iconBoth = RGFW_iconTaskbar | RGFW_iconWindow
};

typedef RGFW_ENUM(u8, RGFW_flashRequest) {
	RGFW_flashCancel = 0,
	RGFW_flashBriefly,
	RGFW_flashUntilFocused
};

typedef RGFW_ENUM(u8, RGFW_debugType) {
	RGFW_typeError = 0, RGFW_typeWarning, RGFW_typeInfo
};

typedef struct RGFW_monitorMode {
	i32 w, h;
	u32 refreshRate;
	u8 red, blue, green;
} RGFW_monitorMode;

typedef struct RGFW_monitor {
	i32 x, y;
	char name[128];
	float scaleX, scaleY;
	float pixelRatio;
	float physW, physH;
	RGFW_monitorMode mode;
} RGFW_monitor;

typedef RGFW_ENUM(u8, RGFW_modeRequest) {
	RGFW_monitorScale = RGFW_BIT(0),
	RGFW_monitorRefresh = RGFW_BIT(1),
	RGFW_monitorRGB = RGFW_BIT(2),
	RGFW_monitorAll = RGFW_monitorScale | RGFW_monitorRefresh | RGFW_monitorRGB
};

typedef RGFW_ENUM(i32, RGFW_glReleaseBehavior)   {
	RGFW_glReleaseFlush = 0,
	RGFW_glReleaseNone
};

typedef RGFW_ENUM(i32, RGFW_glProfile)  {
	RGFW_glCore = 0,
	RGFW_glForwardCompatibility,
	RGFW_glCompatibility,
	RGFW_glES
};

typedef RGFW_ENUM(i32, RGFW_glRenderer)  {
	RGFW_glAccelerated = 0,
	RGFW_glSoftware
};

